-- Hand-written starter examples for the most-used courses (자료구조, 자연어처리개론, 인공지능프로그래밍실습).
-- The cache key is computed exactly like the Edge Function (SHA-256 of the JSON-encoded concept fields),
-- and existing rows (e.g. real Gemini results) are never overwritten.
insert into public.c2c_concept_examples (cache_key, concept_ids, examples, model)
select
  encode(sha256(convert_to('[[' || to_json(k.id::text)::text || ',' || to_json(coalesce(k.name, ''))::text || ',' ||
    to_json(coalesce(k.description, ''))::text || ',' || to_json(coalesce(k.concept_group, ''))::text || ']]', 'UTF8')), 'hex'),
  array[k.id], v.examples::jsonb, 'manual-seed'
from (values
  (2, $j$[{"title":"프로그램의 함수 호출 스택","description":"함수가 호출될 때마다 실행 정보를 쌓고 끝나면 맨 위부터 꺼내 이전 위치로 돌아가요. 재귀 호출과 오류 추적의 바탕이에요.","topic":"운영체제"},{"title":"문서 편집기의 실행 취소(Undo)","description":"편집 작업을 스택에 쌓아 두면 Ctrl+Z로 가장 최근 작업부터 되돌릴 수 있어요. 다시 실행은 별도 스택으로 관리해요.","topic":"앱 개발"},{"title":"컴파일러의 괄호·수식 검사","description":"여는 괄호를 스택에 넣고 닫는 괄호가 나오면 꺼내 짝을 비교해요. 코드의 괄호 오류를 찾고 수식을 계산하는 데 쓰여요.","topic":"컴파일러"}]$j$),
  (3, $j$[{"title":"메시지 큐 기반 주문 처리","description":"주문 요청을 RabbitMQ 같은 메시지 큐에 넣고 들어온 순서대로 처리해요. 요청이 몰려도 서버가 순서를 지키며 안정적으로 소화해요.","topic":"백엔드"},{"title":"CPU 스케줄러의 준비 큐","description":"실행을 기다리는 프로세스를 큐에 세우고 차례대로 CPU를 나눠 줘요. 라운드 로빈 방식에서는 시간이 끝나면 다시 줄 끝으로 가요.","topic":"운영체제"},{"title":"푸시 알림 발송 대기열","description":"수많은 사용자에게 보낼 알림을 큐에 쌓고 순서대로 전송해요. 한꺼번에 몰려도 먼저 요청한 알림부터 처리할 수 있어요.","topic":"서비스 운영"}]$j$),
  (4, $j$[{"title":"실시간 인기 검색어 상위 K개","description":"크기 K의 최소 힙으로 점수가 가장 낮은 항목을 밀어내며 상위 K개만 유지해요. 전체를 정렬하지 않아 빠르고 메모리도 적게 써요.","topic":"검색 서비스"},{"title":"다익스트라 최단 경로 탐색","description":"아직 방문하지 않은 지점 중 거리가 가장 짧은 곳을 힙에서 바로 꺼내요. 내비게이션의 경로 계산에 쓰이는 방식이에요.","topic":"길찾기"},{"title":"스트리밍 데이터의 중앙값 계산","description":"최대 힙과 최소 힙 두 개로 값을 반씩 나눠 담으면 데이터가 계속 들어와도 중앙값을 빠르게 구할 수 있어요.","topic":"데이터 처리"}]$j$),
  (5, $j$[{"title":"운영체제의 프로세스 스케줄링","description":"우선순위가 높은 작업을 먼저 CPU에 배정해요. 화면 입력처럼 급한 작업이 백그라운드 작업보다 먼저 처리되도록 해요.","topic":"운영체제"},{"title":"네트워크 패킷 우선 전송(QoS)","description":"화상통화 패킷을 파일 다운로드보다 먼저 보내도록 우선순위 큐로 정렬해요. 지연에 민감한 서비스의 품질을 지킬 수 있어요.","topic":"네트워크"},{"title":"A* 알고리즘의 길찾기","description":"다음에 살펴볼 지점을 예상 비용이 낮은 순으로 꺼내요. 게임 캐릭터가 장애물을 피해 목적지까지 가는 길을 찾을 때 쓰여요.","topic":"게임 AI"}]$j$),
  (6, $j$[{"title":"로그인 세션 저장소","description":"세션 ID를 키로 사용자 정보를 저장하면 요청마다 거의 즉시 조회할 수 있어요. Redis 같은 키-값 저장소가 이 원리를 활용해요.","topic":"백엔드"},{"title":"URL 단축 서비스의 주소 조회","description":"짧은 코드를 키, 원래 주소를 값으로 저장해요. 단축 링크를 누르면 코드로 원본 주소를 바로 찾아 이동시켜 줘요.","topic":"웹 서비스"},{"title":"단어 빈도수 세기와 중복 검사","description":"딕셔너리(HashMap)에 단어를 키로 넣어 등장 횟수를 세요. 데이터가 많아도 중복 여부를 빠르게 확인할 수 있어요.","topic":"데이터 처리"}]$j$),
  (7, $j$[{"title":"정렬 상태를 유지하는 TreeMap","description":"값을 넣을 때마다 이진 탐색 트리 구조로 자리를 잡아 항상 정렬된 상태를 유지해요. 범위 조회와 최솟값 찾기가 쉬워요.","topic":"자바 컬렉션"},{"title":"데이터베이스의 인덱스 탐색","description":"DB 인덱스는 이진 탐색 트리를 확장한 B-트리 계열로 키를 정리해요. 수백만 건에서도 몇 번의 비교로 원하는 행을 찾아요.","topic":"데이터베이스"},{"title":"일정·예약 시간 충돌 확인","description":"예약 시간을 정렬된 트리에 저장하면 새 예약이 기존 시간과 겹치는지 빠르게 확인할 수 있어요. 회의실 예약 시스템에 쓰여요.","topic":"서비스 개발"}]$j$),
  (8, $j$[{"title":"파일 탐색기의 폴더 용량 계산","description":"하위 폴더를 먼저 방문하고 돌아오며 크기를 더하는 후위 순회로 폴더 전체 용량을 구해요. 디스크 사용량 분석에 쓰여요.","topic":"파일 시스템"},{"title":"웹 브라우저의 DOM 탐색","description":"웹 페이지는 태그가 계층으로 이어진 트리예요. 순회하며 조건에 맞는 요소를 찾아 querySelector 같은 기능이 동작해요.","topic":"웹 개발"},{"title":"코드 분석기의 구문 트리 순회","description":"소스 코드를 트리로 바꾼 뒤 노드를 순서대로 방문해요. 린터가 문제 있는 코드를 찾거나 코드 포맷터가 정리할 때 쓰여요.","topic":"개발 도구"}]$j$),
  (11, $j$[{"title":"이미지 필터의 픽셀 버퍼","description":"화면 픽셀을 연속된 배열에 담으면 좌표만으로 위치를 계산해 바로 읽고 고칠 수 있어요. 밝기 조절 같은 필터가 빠르게 처리돼요.","topic":"그래픽스"},{"title":"NumPy 배열 기반 데이터 연산","description":"같은 자료형을 연속 메모리에 두는 배열 덕분에 수백만 개 값을 한 번에 계산할 수 있어요. 데이터 분석과 AI 전처리의 기본이에요.","topic":"데이터 분석"},{"title":"게임 타일맵 좌표 조회","description":"맵을 2차원 배열로 저장하면 좌표로 타일을 즉시 찾아요. 충돌 판정이나 이동 가능 여부 확인이 간단하고 빨라져요.","topic":"게임 개발"}]$j$),
  (12, $j$[{"title":"브라우저 뒤로·앞으로 가기","description":"방문한 페이지를 앞뒤로 잇는 이중 연결 리스트로 모델링하면, 현재 위치에서 이전·다음 페이지로 바로 이동할 수 있어요.","topic":"이중 연결 리스트"},{"title":"음악 앱 플레이리스트 순서 변경","description":"곡을 노드로 연결해 두면 중간에 곡을 끼우거나 빼도 연결만 바꾸면 돼요. 배열처럼 뒤 항목을 전부 밀 필요가 없어요.","topic":"삽입·삭제"},{"title":"메모리 할당기의 빈 블록 목록","description":"해제된 메모리 조각을 연결 리스트로 이어 두고 필요할 때 하나씩 꺼내 써요. 크기가 제각각인 블록을 유연하게 관리해요.","topic":"시스템"}]$j$),
  (18, $j$[{"title":"컴파일러의 수식 트리","description":"3 + 4 * 2 같은 수식을 연산자는 부모, 피연산자는 자식인 이진 트리로 나타내요. 이 트리를 따라가며 계산 순서를 결정해요.","topic":"컴파일러"},{"title":"허프만 코딩 기반 파일 압축","description":"자주 나오는 문자는 짧은 코드, 드문 문자는 긴 코드를 주는 이진 트리를 만들어요. 압축 형식에서 쓰이는 기법이에요.","topic":"데이터 압축"},{"title":"의사결정 트리 모델","description":"조건마다 예·아니오로 갈라지는 이진 트리로 결과를 예측해요. 대출 심사나 고객 이탈 예측처럼 판단 근거 설명이 필요할 때 쓰여요.","topic":"머신러닝"}]$j$),
  (21, $j$[{"title":"SNS 친구 추천","description":"사용자를 정점, 친구 관계를 간선으로 두고 친구의 친구를 찾아 추천해요. 서로 아는 사람이 많을수록 연결 가능성이 높다고 봐요.","topic":"소셜 네트워크"},{"title":"지도 앱의 길 찾기","description":"교차로를 정점, 도로를 간선으로 표현하고 거리나 시간을 가중치로 둬요. 출발지에서 도착지까지 최적 경로를 계산해요.","topic":"지도·내비게이션"},{"title":"패키지 의존성 관리","description":"npm 같은 도구는 라이브러리 간 의존 관계를 방향 그래프로 다뤄요. 어떤 패키지를 먼저 설치할지 정할 때 이 구조를 활용해요.","topic":"개발 도구"}]$j$),
  (22, $j$[{"title":"빌드 도구의 작업 실행 순서","description":"작업 간 의존 관계를 깊이 우선 탐색으로 따라가 먼저 끝나야 할 작업 순서를 정해요. 위상 정렬 방식으로 Gradle, Make 등에 쓰여요.","topic":"빌드 시스템"},{"title":"미로 탐색과 퍼즐 풀이","description":"한 길을 끝까지 가 보고 막히면 되돌아와 다른 길을 시도해요. 미로 게임이나 스도쿠처럼 경우를 하나씩 따지는 문제에 쓰여요.","topic":"게임·퍼즐"},{"title":"순환 의존성 탐지","description":"탐색 중 이미 방문 중인 정점을 다시 만나면 순환 구조예요. 모듈이 서로를 참조하는 문제를 코드 분석 도구가 찾아낼 때 쓰여요.","topic":"코드 분석"}]$j$),
  (23, $j$[{"title":"SNS 몇 다리 건너 아는 사이","description":"내 친구, 친구의 친구 순으로 가까운 관계부터 단계별로 탐색해요. 두 사람이 몇 단계로 연결되는지 계산할 수 있어요.","topic":"소셜 네트워크"},{"title":"지하철 최소 환승 경로","description":"출발역에서 가까운 역부터 단계적으로 퍼져 나가요. 간선 비용이 같은 노선도에서는 환승 횟수가 가장 적은 길을 찾아줘요.","topic":"교통 서비스"},{"title":"웹 크롤러의 링크 수집","description":"시작 페이지의 링크를 모두 수집한 뒤 그 링크들의 링크로 층층이 넓혀 가요. 검색 엔진이 웹 페이지를 모으는 방식이에요.","topic":"검색 엔진"}]$j$),
  (24, $j$[{"title":"쇼핑몰 상품 정렬","description":"가격 낮은 순, 인기순, 최신순처럼 기준을 바꿔 정렬해요. 같은 값의 순서를 유지하는 안정 정렬이 쓰이면 결과가 더 자연스러워요.","topic":"이커머스"},{"title":"데이터베이스의 ORDER BY","description":"DB는 쿼리 결과를 정렬할 때 병합 정렬 계열 알고리즘을 써요. 메모리보다 큰 데이터는 나눠 정렬한 뒤 합치는 방식으로 처리해요.","topic":"데이터베이스"},{"title":"게임 리더보드 순위 계산","description":"점수를 기준으로 정렬해 순위를 매겨요. 동점 처리 규칙과 정렬 성능이 많은 사용자의 실시간 순위 표시에 영향을 줘요.","topic":"게임 서비스"}]$j$),
  (25, $j$[{"title":"git bisect로 버그 커밋 찾기","description":"정상이던 시점과 문제가 생긴 시점의 중간 커밋을 반복 확인해요. 수백 개 커밋도 이진 탐색으로 몇 번 만에 원인을 좁혀요.","topic":"개발 도구"},{"title":"정렬된 로그에서 시간대 검색","description":"시간순 로그에서 이진 탐색으로 시작 시각 위치를 찾아요. 방대한 로그 파일에서도 처음부터 읽지 않고 필요한 구간만 열어요.","topic":"로그 분석"},{"title":"앱 안의 연락처·사전 검색","description":"정렬된 목록이면 이진 탐색으로, 아니면 선형 탐색으로 항목을 찾아요. 데이터가 정렬됐는지가 검색 방식과 속도를 좌우해요.","topic":"앱 개발"}]$j$),
  (94, $j$[{"title":"검색엔진의 형태소 분석과 색인","description":"문장을 단어 단위로 나누고 조사를 정리해 색인을 만들어요. 같은 의미의 표현이 서로 검색될 수 있어요.","topic":"검색 엔진"},{"title":"LLM 입력의 토큰화","description":"챗봇은 문장을 토큰으로 잘라 숫자로 바꿔 입력받아요. 토큰 수가 처리 가능한 길이와 API 사용 비용에 영향을 줘요.","topic":"생성형 AI"},{"title":"리뷰 감성 분석 전처리","description":"이모티콘, 오타, 불필요한 기호를 정리하고 형태를 통일해요. 분석 모델이 같은 의미의 표현을 일관되게 받아들이게 해요.","topic":"데이터 정제"}]$j$),
  (95, $j$[{"title":"의미 기반 검색(시맨틱 검색)","description":"문장을 벡터로 바꿔 질문과 뜻이 비슷한 문서를 찾아요. 단어가 정확히 일치하지 않아도 관련된 결과를 보여줄 수 있어요.","topic":"검색"},{"title":"RAG 챗봇의 문서 검색","description":"사내 문서를 임베딩해 벡터 DB에 저장하고, 질문과 가까운 문서를 찾아 답변 근거로 사용해요. 최신 정보 반영에 유용해요.","topic":"생성형 AI"},{"title":"유사 상품 추천","description":"상품 설명을 벡터로 바꿔 서로 가까운 상품을 찾아요. 같은 카테고리가 아니어도 취향이 비슷한 상품을 추천할 수 있어요.","topic":"추천 시스템"}]$j$),
  (96, $j$[{"title":"스마트폰 키보드 다음 단어 추천","description":"지금까지 입력한 단어를 바탕으로 다음에 올 가능성이 높은 단어를 예측해 보여줘요. 타이핑 시간을 줄여줘요.","topic":"모바일"},{"title":"코드 자동완성 도구","description":"앞의 코드 문맥으로 다음에 올 코드를 확률적으로 예측해요. 개발자가 반복 코드를 빠르게 작성하도록 도와줘요.","topic":"개발 도구"},{"title":"챗봇의 답변 생성","description":"질문 뒤에 이어질 단어를 확률로 하나씩 골라 문장을 만들어요. 언어 모델링 목표로 학습한 모델이 대화 응답의 바탕이 돼요.","topic":"생성형 AI"}]$j$),
  (97, $j$[{"title":"스팸 메일 필터","description":"메일 내용을 보고 스팸인지 아닌지 분류해요. 잘못 걸러 중요한 메일이 사라지는 일이 없도록 정밀도와 재현율을 함께 봐요.","topic":"이메일"},{"title":"고객 문의 자동 분류","description":"문의 글을 결제, 배송, 환불 같은 범주로 분류해 담당 부서로 바로 전달해요. 처리 시간을 줄이고 담당자의 부담을 낮춰요.","topic":"고객 지원"},{"title":"상품 리뷰 감성 분석","description":"리뷰가 긍정인지 부정인지 분류해 상품 평가를 요약해요. 부정 리뷰가 늘어나는 상품을 빠르게 찾아 대응할 수 있어요.","topic":"데이터 분석"}]$j$),
  (98, $j$[{"title":"이력서 항목 자동 추출","description":"이력서 텍스트에서 이름, 학력, 경력, 보유 기술을 찾아 항목별로 정리해요. 채용 시스템이 지원서를 자동 입력하도록 도와줘요.","topic":"채용 서비스"},{"title":"뉴스 속 기업·인물 개체명 추출","description":"기사에서 회사, 사람, 지역 이름을 찾아 관계를 정리해요. 이 정보를 모아 지식 그래프나 뉴스 검색에 활용할 수 있어요.","topic":"지식 그래프"},{"title":"영수증·계약서 정보 입력 자동화","description":"문서 텍스트에서 날짜, 금액, 상호명을 찾아 필드에 채워 줘요. 회계 처리나 문서 관리의 수작업을 줄여줘요.","topic":"업무 자동화"}]$j$),
  (99, $j$[{"title":"기계 번역 서비스","description":"문장 안의 단어들이 서로 얼마나 관련 있는지 계산하는 어텐션으로 문맥을 파악해요. 긴 문장도 자연스럽게 번역할 수 있어요.","topic":"번역"},{"title":"대화형 AI 챗봇","description":"트랜스포머 구조의 언어 모델이 질문의 중요한 부분에 주목하며 답을 생성해요. 긴 대화의 앞선 맥락도 함께 반영해요.","topic":"생성형 AI"},{"title":"긴 문서 요약","description":"문서에서 중요한 문장에 높은 가중치를 두고 핵심을 간추려요. 회의록이나 논문, 뉴스 기사를 빠르게 파악할 때 쓰여요.","topic":"문서 처리"}]$j$),
  (112, $j$[{"title":"추천 시스템의 로그 수집·정제","description":"클릭과 구매 로그를 모아 중복과 이상값을 제거하고 학습용 형태로 바꿔요. 매일 같은 과정을 자동으로 반복하는 파이프라인이에요.","topic":"데이터 엔지니어링"},{"title":"챗봇 학습 데이터 준비","description":"대화 데이터에서 개인정보를 지우고 품질이 낮은 문장을 걸러요. 학습용과 검증용으로 나눠 평가의 공정성을 지켜요.","topic":"데이터 정제"},{"title":"이미지 분류용 데이터 구성","description":"이미지를 수집하고 라벨을 확인한 뒤 크기를 맞춰요. 회전이나 밝기 변화를 더해 데이터를 늘리면 모델이 더 안정적으로 학습해요.","topic":"컴퓨터 비전"}]$j$),
  (113, $j$[{"title":"스마트폰 얼굴 인식 잠금 해제","description":"모델은 서버에서 학습하고, 사용자의 기기에서는 학습된 모델로 얼굴을 빠르게 판별해요. 학습과 추론의 역할이 서로 달라요.","topic":"모바일 AI"},{"title":"번역 API의 추론 서버","description":"학습이 끝난 모델을 서버에 올려 요청이 올 때마다 번역 결과를 계산해요. 응답 속도와 처리량이 서비스 품질을 좌우해요.","topic":"서비스 운영"},{"title":"추천 모델의 주기적 재학습","description":"새 사용자 행동 데이터로 모델을 정기적으로 다시 학습해요. 실시간 추천은 최신 모델로 추론만 수행해 빠르게 응답해요.","topic":"추천 시스템"}]$j$),
  (114, $j$[{"title":"중고 거래 가격 예측","description":"카테고리는 원-핫 인코딩으로, 사용 기간 같은 수치는 정규화로 바꿔 모델에 넣어요. 입력 표현에 따라 예측 품질이 달라져요.","topic":"예측 모델"},{"title":"고객 이탈 예측 모델","description":"가입 기간, 사용 빈도, 요금제 같은 값을 모델이 쓸 수 있는 숫자로 바꿔요. 의미 있는 특성을 고르는 것이 성능을 좌우해요.","topic":"데이터 분석"},{"title":"스팸 분류의 TF-IDF 특성","description":"문서 안에서 중요한 단어에 높은 값을 주는 TF-IDF로 텍스트를 숫자로 표현해요. 글자를 모델이 계산할 수 있는 형태로 바꿔줘요.","topic":"텍스트 분석"}]$j$),
  (115, $j$[{"title":"의료 영상 진단 보조 평가","description":"질병을 놓치지 않는 것이 중요해서 정확도보다 재현율을 중점으로 평가해요. 놓친 사례를 분석해 학습 데이터를 보완해요.","topic":"의료 AI"},{"title":"카드 사기 탐지 모델 평가","description":"사기는 드물어서 정확도만 보면 성능을 오해해요. 정밀도와 재현율을 함께 보고 오탐 사례를 분석해 기준을 조정해요.","topic":"금융 AI"},{"title":"챗봇 실패 사례 분류와 개선","description":"틀린 답변을 질문 이해 오류, 지식 부족 같은 유형으로 나눠요. 유형별 빈도를 보고 데이터와 모델 중 무엇을 고칠지 정해요.","topic":"서비스 개선"}]$j$),
  (116, $j$[{"title":"실험 추적 도구(MLflow 등) 활용","description":"모델 설정값, 데이터 버전, 결과 지표를 실험마다 기록해요. 어떤 설정이 가장 좋았는지 나중에도 비교하고 다시 재현할 수 있어요.","topic":"MLOps"},{"title":"난수 시드 고정과 팀 협업","description":"시드와 라이브러리 버전을 기록하면 팀원이 같은 코드로 같은 결과를 얻어요. 성능 차이가 코드 때문인지 우연인지 가려낼 수 있어요.","topic":"협업"},{"title":"데이터 버전 관리와 모델 롤백","description":"학습에 쓴 데이터와 코드를 버전으로 남겨요. 새 모델 성능이 나빠지면 이전 버전을 그대로 되살려 서비스를 안정시킬 수 있어요.","topic":"MLOps"}]$j$)
) as v(id, examples)
join public.c2c_course_concepts k on k.id = v.id
on conflict (cache_key) do nothing;
